DROP TABLE IF EXISTS `diagnosis_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `diagnosis_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `doctor_id` int DEFAULT NULL,
  `patient_id` int DEFAULT NULL,
  `consultation_id` int DEFAULT NULL,
  `input_symptoms` text COLLATE utf8mb4_unicode_ci,
  `input_clinical_findings` text COLLATE utf8mb4_unicode_ci,
  `input_lab_tests` text COLLATE utf8mb4_unicode_ci,
  `suggested_diagnoses` json DEFAULT NULL,
  `confidence_scores` json DEFAULT NULL,
  `ai_analysis` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_doctor` (`doctor_id`),
  KEY `idx_patient` (`patient_id`),
  KEY `idx_consultation` (`consultation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

