DROP TABLE IF EXISTS `diseases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `diseases` (
  `id` int NOT NULL AUTO_INCREMENT,
  `disease_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `icd_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` enum('infectious','respiratory','cardiovascular','digestive','neurological','musculoskeletal','endocrine','urological','dermatological','psychiatric','hematological','immunological','oncological','pediatric','gynecological','ophthalmic','ent','dental','emergency','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `sub_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `primary_symptoms` text COLLATE utf8mb4_unicode_ci,
  `secondary_symptoms` text COLLATE utf8mb4_unicode_ci,
  `warning_signs` text COLLATE utf8mb4_unicode_ci,
  `typical_onset` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `typical_duration` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `age_groups` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender_predisposition` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `clinical_findings` text COLLATE utf8mb4_unicode_ci,
  `lab_tests` text COLLATE utf8mb4_unicode_ci,
  `imaging` text COLLATE utf8mb4_unicode_ci,
  `differential_diagnosis` text COLLATE utf8mb4_unicode_ci,
  `conventional_treatment` text COLLATE utf8mb4_unicode_ci,
  `homeopathic_approach` text COLLATE utf8mb4_unicode_ci,
  `lifestyle_modifications` text COLLATE utf8mb4_unicode_ci,
  `severity_level` enum('mild','moderate','severe','critical') COLLATE utf8mb4_unicode_ci DEFAULT 'moderate',
  `urgency_level` enum('routine','urgent','emergency') COLLATE utf8mb4_unicode_ci DEFAULT 'routine',
  `contagious` tinyint(1) DEFAULT '0',
  `reference_source` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `disease_name` (`disease_name`),
  KEY `idx_category` (`category`),
  KEY `idx_icd` (`icd_code`),
  KEY `idx_severity` (`severity_level`),
  FULLTEXT KEY `idx_symptoms_search` (`disease_name`,`primary_symptoms`,`secondary_symptoms`,`clinical_findings`,`warning_signs`,`description`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

